
// import { v4 as uuidv4 } from 'uuid';
import { generateDeck } from '../constants/cards';
import type { Player, Team, TricksterObjective } from '../types/game';

const TEAM_DISTRIBUTION: Record<number, { RED: number; BLUE: number; TRICKSTER: number }> = {
    3: { RED: 1, BLUE: 1, TRICKSTER: 1 },
    4: { RED: 1, BLUE: 1, TRICKSTER: 2 }, // Fallback for 4 (Not recommended)
    5: { RED: 2, BLUE: 2, TRICKSTER: 1 },
    6: { RED: 2, BLUE: 2, TRICKSTER: 2 },
    7: { RED: 2, BLUE: 2, TRICKSTER: 3 },
    8: { RED: 3, BLUE: 3, TRICKSTER: 2 }
};

const TRICKSTER_OBJECTIVES: TricksterObjective[] = [
    'REAPER', 'ANARCHIST', 'SADIST', 'SAINT', 'SURVIVOR', 'MARTYR', 'GAMBLER', 'PROPHET'
];

const CPU_NAMES = [
    'カイト', 'レン', 'ルナ', 'ソラ', 'ノア',
    'レオ', 'アリス', 'シオン', 'レイ', 'ユウ',
    'サラ', 'アラン', 'ミオ', 'リク', 'エマ',
    'ハルト', 'メイ', 'ジン', 'ロイ', 'ニーナ'
];

const generateRandomNames = (count: number): string[] => {
    // Shuffle the name listdata:image/png;base64,
    const shuffled = [...CPU_NAMES].sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count);
};

export const setupNewGame = (playerCount: number, userName: string): { players: Player[]; deck: any[] } => {
    // 1. Determine Distribution
    const dist = TEAM_DISTRIBUTION[playerCount] || TEAM_DISTRIBUTION[3];

    // 2. Create Team Array & Shuffle
    let teams: Team[] = [];
    for (let i = 0; i < dist.RED; i++) teams.push('RED');
    for (let i = 0; i < dist.BLUE; i++) teams.push('BLUE');
    for (let i = 0; i < dist.TRICKSTER; i++) teams.push('TRICKSTER');

    // Fisher-Yates Shuffle
    for (let i = teams.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [teams[i], teams[j]] = [teams[j], teams[i]];
    }

    // Generate Names for all potential CPUs
    const cpuNames = generateRandomNames(playerCount);

    // 3. Create Players
    const players: Player[] = [];
    for (let i = 0; i < playerCount; i++) {
        const isUser = i === 0;
        const id = isUser ? 'player-1' : `player-${i + 1}`;
        // Set name: User gets their input, CPUs get from list
        const name = isUser ? userName : cpuNames[i];
        const team = teams[i];

        let tricksterObjective: TricksterObjective | undefined;

        if (team === 'TRICKSTER') {
            tricksterObjective = TRICKSTER_OBJECTIVES[Math.floor(Math.random() * TRICKSTER_OBJECTIVES.length)];
        }

        players.push({
            id,
            name,
            team,
            hp: 10,
            maxHp: 10,
            hand: [],
            isAlive: true,
            isRevealed: false,
            isTurn: false, // Set explicitly later
            isPhoenixActive: false,
            statusEffects: [],
            tricksterObjective,
            killCount: 0,
            damageDealt: 0,
            turnsAtOneHp: 0,
            mysteryStarUsage: 0,
            infoCardUsage: 0,
            infoTypesUsed: [],
            healingDone: 0,
            actionsRemaining: 0 // Initialize at 0, updated by START_TURN
        });
    }

    // 4. Generate Deck
    let deck = generateDeck();

    // 5. Initial Rigged Deal (Guarantee 1 Info Card per Player for Round 1)

    // Extract Info Cards
    const infoCards = deck.filter(c => c.type === 'INFO');
    const otherCards = deck.filter(c => c.type !== 'INFO');

    // Shuffle separated piles just in case (though generateDeck shuffles)
    // We want to ensure distribution is random among Info cards

    players.forEach(player => {
        // 1. Give 1 Info Card
        if (infoCards.length > 0) {
            player.hand.push(infoCards.pop()!); // Use non-null assertion as we have 12 info cards, enough for 8 players
        }
        // 2. Give 2 Random Cards (from 'otherCards' to avoid giving 2 info cards? 
        //    Actually, random is fine, but to ensure diversity maybe take from mixed remaining?
        //    Let's just take from 'otherCards' to ensure exactly 1 Info card? 
        //    User said "Make sure everyone gets an Info card". It doesn't ban getting 2.
        //    But to balance, maybe just 1 is safer.
        //    For simplicity, let's put remaining Info cards back into pool and shuffle, then draw 2.
    });

    // Recombine remaining Info cards with others
    let remainingPool = [...otherCards, ...infoCards];

    // Simple shuffle function for the pool
    for (let i = remainingPool.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [remainingPool[i], remainingPool[j]] = [remainingPool[j], remainingPool[i]];
    }

    // Distribute 2 more cards to each player
    players.forEach(player => {
        for (let i = 0; i < 2; i++) {
            if (remainingPool.length > 0) {
                player.hand.push(remainingPool.pop()!);
            }
        }
    });

    return { players, deck: remainingPool };
};
